from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="200" viewBox="0 0 680 200" role="img">\n<title>Tetris stack</title><desc>tetrominoes drop 0.8s clear flash 0.3s</desc>\n<style>@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}} @keyframes drop{0%{transform:translateY(-40px)}100%{transform:translateY(0)}} .d1{animation:drop .8s forwards} .d2{animation:drop .8s .8s forwards} .d3{animation:drop .8s 1.6s forwards} @keyframes flash{0%,100%{opacity:1}50%{opacity:.3}} .clear{animation:flash .3s 2.4s 3}</style>\n<rect width="680" height="200" rx="16" fill="#0f172a"/>\n<text x="20" y="28" fill="#e2e8f0" font-family="monospace" font-size="12">TETRIS — contributions stack like blocks</text>\n<g transform="translate(40,40)">\n  <rect width="160" height="120" rx="6" fill="#020617" stroke="#1e293b"/>\n  <!-- stacked blocks -->\n  <g class="d1"><rect x="40" y="80" width="80" height="16" rx="2" fill="#22c55e"/><rect x="40" y="96" width="80" height="16" rx="2" fill="#22c55e" class="clear"/></g>\n  <g class="d2"><rect x="20" y="64" width="60" height="16" rx="2" fill="#38bdf8"/><rect x="80" y="64" width="60" height="16" rx="2" fill="#f59e0b"/></g>\n  <g class="d3"><rect x="60" y="20" width="40" height="40" rx="3" fill="#a78bfa"/></g>\n  <text x="200" y="30" fill="#e2e8f0" font-family="monospace" font-size="11">Line clear!</text>\n  <text x="200" y="50" fill="#94a3b8" font-family="monospace" font-size="10">Each full week = cleared line</text>\n  <text x="200" y="70" fill="#64748b" font-family="monospace" font-size="9">idea: github tetris / leds-play</text>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','tetris-stack.svg').write_text(svg, encoding='utf-8')
print('Wrote assets/tetris-stack.svg')
